 for j in range(n):
  nz=np.where(M[rr:,j])[0]
  if not len(nz): continue
  k=rr+nz[0]; M[[rr,k]]=M[[k,rr]]
  for i in range(m):
   if i!=rr and M[i,j]: M[i]^=M[rr]
  piv.append(j); rr+=1
  if rr==m:break
 if any(np.all(row[:n]==0) and row[n] for row in M):return None
 free=[j for j in range(n) if j not in piv]; sol=np.zeros(n,dtype=np.uint8)
 # free=0 backsolve row pivots
 for i,j in reversed(list(enumerate(piv))): sol[j]=M[i,n] ^ (np.dot(M[i,:n],sol)%2)
 return sol,piv,free
